// Match Brand v2: finds the brand row in the n8n Data Table (fuzzy on brand_name / ig_id)
// and builds the brand context text. Input = all rows from "Get Brand Rows".

const p = $('Parse Input').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && String(r.brand_name || '').trim());

const clean = (s) =>
  String(s == null ? '' : s)
    .replace(/^\uFEFF/, '')
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
const norm = (s) => clean(s).toLowerCase().replace(/^@/, '').replace(/[^a-z0-9]/g, '');
const escH = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const names = rows.map((r) => clean(r.brand_name));
const fail = (why) => [{
  json: {
    proceed: false,
    errorMessage: escH(
      why + '\n\n' +
      (names.length
        ? 'Available brands: ' + names.join(', ')
        : 'No brand rows found in the Data Table. Check table selection / data import.') +
      '\n\nWrite one of these names after "Brand:".'
    ),
  },
}];

const q = norm(p.brandQuery);
if (!q) return fail('Brand name is empty.');

const scored = rows.map((r) => {
  const n = norm(r.brand_name);
  const ig = norm(r.ig_id);
  const first = norm(clean(r.brand_name).split(/\s+/)[0]);
  let s = 0;
  if (q === n || (ig && q === ig)) s = 100;
  else if (q.length >= 3 && (n.includes(q) || (n.length >= 3 && q.includes(n)))) s = 80;
  else if (q.length >= 3 && ig && (ig.includes(q) || (ig.length >= 3 && q.includes(ig)))) s = 75;
  else if (first.length >= 4 && (q.startsWith(first) || first.startsWith(q))) s = 70;
  return { r, s };
}).filter((x) => x.s > 0).sort((a, b) => b.s - a.s);

if (!scored.length) {
  return fail('Brand "' + p.brandQuery + '" was not found in the Data Table.');
}
if (scored.length > 1 && scored[0].s === scored[1].s && scored[0].s < 100) {
  return fail(
    'Brand "' + p.brandQuery + '" matched more than one row (' +
    scored.filter((x) => x.s === scored[0].s).map((x) => clean(x.r.brand_name)).join(', ') +
    '). Use the full name.'
  );
}

const b = scored[0].r;
const g = (k) => clean(b[k]);
const place = [g('city'), g('state'), g('country')].filter(Boolean).join(', ');

const lines = [
  ['Brand', g('brand_name')],
  ['Instagram', g('ig_id')],
  ['Industry', g('industry')],
  ['About', g('about')],
  ['Products / services', g('products_services')],
  ['USPs', g('usps')],
  ['Target audience', g('target_audience')],
  ['Audience age', g('audience_age')],
  ['Audience interests', g('audience_interests')],
  ['Location', place],
  ['Service area', g('service_area')],
  ['Brand goal', g('goal')],
  ['Brand tone', g('tone')],
  ['Brand default CTA', g('default_cta')],
  ['Brand notes', g('notes')],
  ['Link', g('link')],
].filter(([, v]) => v);

const brandText = lines.map(([k, v]) => k + ': ' + v).join('\n').slice(0, 15000);

return [{
  json: {
    proceed: true,
    brandName: g('brand_name'),
    brandText,
    hasBrand: brandText.length > 0,
    docStatus: 'ok',
    docChars: brandText.length,
    brandWarning: '',
  },
}];

// Pick Folder Video: takes the Drive folder listing and picks the newest video file.
const r = $input.first().json;
const escH = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fail = (why) => [{
  json: {
    ok: false,
    errorMessage: escH('Could not get video from Drive folder: ' + why),
  },
}];

if (r.error) {
  const m = (typeof r.error === 'string'
    ? r.error
    : (r.error.message || JSON.stringify(r.error))
  ).toString().slice(0, 220);
  return fail(m + ' (Is the Drive credential connected? Is the folder shared with that account?)');
}

const files = (Array.isArray(r.files) ? r.files : []).filter(
  (f) => f && /^video\//i.test(f.mimeType || '')
);
if (!files.length) {
  return fail(
    'No video file in the folder, or the folder is not shared with the Google account connected in n8n.'
  );
}

// API already returns newest first (orderBy createdTime desc).
const f = files[0];
return [{
  json: {
    ok: true,
    isDrive: true,
    fileId: f.id,
    fileName: f.name || '',
    mimeType: f.mimeType || 'video/mp4',
    sizeBytes: Number(f.size || 0),
    videoCountInFolder: files.length,
    downloadUrl:
      'https://www.googleapis.com/drive/v3/files/' + f.id + '?alt=media&supportsAllDrives=true',
  },
}];

// Resolve Direct Ref: Drive file link -> Drive API download URL; any other link -> used as a direct video URL.
const p = $('Parse Input').first().json;

if (p.refType === 'drivefile') {
  return [{
    json: {
      ok: true,
      isDrive: true,
      fileId: p.refId,
      fileName: '',
      mimeType: '',
      sizeBytes: 0,
      downloadUrl: 'https://www.googleapis.com/drive/v3/files/' + p.refId + '?alt=media&supportsAllDrives=true',
    },
  }];
}

return [{
  json: { ok: true, isDrive: false, fileId: '', fileName: '', mimeType: '', sizeBytes: 0, downloadUrl: p.refUrl },
}];

// Video to Base64 v3: the ONLY place where base64 happens. Takes the video downloaded from Drive (Drive API) / direct link,
// converts it to inline_data and builds the full Gemini analysis request.
// Gemini inline requests are capped at ~20 MB total, base64 adds ~33%, so raw video must stay under ~14 MB.
const MODEL = 'gemini-3.5-flash-lite'; // VIDEO ANALYSIS model. Keep it DIFFERENT from GEMINI_MODEL in Build Master Prompt so each model has its own RPM/RPD quota.
const MAX_RAW_BYTES = 14 * 1024 * 1024;

const ref = $('Ref OK?').first().json;
const item = $input.first();

let videoBase64 = null;
let videoStatus = 'ok';
let videoReason = '';
let sizeMB = 0;
let mime = 'video/mp4';

try {
  if (!item.binary || !item.binary.video) throw new Error('no file received');
  const bin = item.binary.video;
  const m = String(bin.mimeType || ref.mimeType || '').toLowerCase();
  if (/^(text|application\/json)/.test(m) || /html/.test(m)) throw new Error('not a video (got ' + m + ')');
  if (/quicktime/.test(m)) mime = 'video/mov';
  else if (/^video\//.test(m)) mime = m;
  const buf = await this.helpers.getBinaryDataBuffer(0, 'video');
  sizeMB = +(buf.length / 1048576).toFixed(1);
  if (buf.length < 20000) throw new Error('file too small to be a video');
  if (buf.length > MAX_RAW_BYTES) { videoStatus = 'too_large'; videoReason = sizeMB + ' MB'; }
  else videoBase64 = buf.toString('base64');
} catch (e) {
  videoStatus = 'download_failed';
  const je = item.json && item.json.error;
  const apiMsg = je ? (typeof je === 'string' ? je : (je.message || JSON.stringify(je))) : '';
  videoReason = (String((e && e.message) || '') + (apiMsg ? ' | ' + String(apiMsg).slice(0, 160) : '')).slice(0, 220);
}

const prompt = `You are a senior short-form video analyst. Watch this Instagram Reel completely (video AND audio, start to end) and break down exactly how it is built: the hook, the spoken script structure, what the creator does on screen, how the CTA is delivered and what keeps people watching. Your analysis will be used as a reusable BLUEPRINT so a writer can build a completely different reel about another topic with the same mechanics.

${videoBase64 ? 'Return ONLY a valid JSON object (no markdown, no code fences) with exactly this shape:' : 'NOTE: the video file is NOT available (' + videoStatus + '). Return ONLY a JSON object with the same shape, set "video_available" to false and fill it with a generic high-retention 30 to 35 second blueprint (hook -> problem -> value -> proof -> CTA).'}
{
  "video_available": true,
  "duration_seconds": 0,
  "spoken_language_style": "language(s) and register, for example casual Hinglish, conversational",
  "format": "talking head / voiceover over b-roll / skit / screen recording / mixed",
  "hook": {
    "technique": "pattern interrupt / bold claim / question / story opener / myth bust / contrast / open loop ...",
    "first_3s_word_count": 0,
    "delivery": "energy, speed, facial expression or visual action in the first 3 seconds, described abstractly",
    "why_it_stops_the_scroll": "the psychological reason it works"
  },
  "beats": [
    { "time": "0-3s", "purpose": "abstract label such as state a relatable problem / reveal the key idea / give one example / social proof / call to action", "approx_words": 0, "pacing": "short or medium sentences, pauses, speed", "creator_does": "what the creator does in this beat: gesture, movement, cut, zoom, text overlay, b-roll, prop handling, described abstractly" }
  ],
  "skeleton": "beat purposes as one chain with seconds and words, for example hook 3s/8w -> problem 6s/15w -> ...",
  "creator_delivery": {
    "on_camera_presence": "eye contact, posture, gestures, facial expressions, how conversational vs scripted it feels",
    "energy_and_speed": "energy level, words per second, use of pauses and emphasis",
    "editing_style": "cut frequency, zooms, captions style, music or sound effects, transitions"
  },
  "cta": {
    "timestamp": "when it appears",
    "type": "comment keyword / save / share / follow / DM / link in bio / visit / order",
    "framing": "how it is framed: favour, curiosity, urgency, reward ...",
    "delivery": "tone and energy of the delivery, how it connects to the previous beat"
  },
  "retention_devices": ["each device used to keep viewers watching: open loops, re-hooks, pattern changes, payoff timing ..."],
  "emotional_arc": "how the viewer's feeling moves from first second to last",
  "tone": "overall tone and personality of the speaker"
}

STRICT RULES: Be factual about what you actually see and hear, never invent. Describe the STRUCTURE and TECHNIQUE only. Do NOT mention or hint at the reel's subject, product, brand, people's names, claims, examples, jokes, statistics, or quote any spoken words, so the blueprint can be reused for ANY topic. Use abstract labels everywhere. Keep each field concise.`;

const parts = [];
if (videoBase64) parts.push({ inline_data: { mime_type: mime, data: videoBase64 } });
parts.push({ text: prompt });

return [{
  json: {
    videoStatus,
    videoReason,
    sizeMB,
    refName: ref.fileName || '',
    model: MODEL,
    geminiBody: {
      contents: [{ role: 'user', parts }],
      generationConfig: {
        temperature: 0.3,
        maxOutputTokens: 8192,
        responseMimeType: 'application/json',
        thinkingConfig: { thinkingBudget: 1024 },
      },
    },
  },
}];

// Extract Analysis v2: parses the Gemini JSON blueprint and turns it into a compact text block for the script writer.
const r = $input.first().json;
const prev = $('Video to Base64').first().json;

let raw = '';
let reason = '';

if (r.error) {
  reason = (r.error.message || JSON.stringify(r.error)).toString().slice(0, 200);
} else if (r.promptFeedback && r.promptFeedback.blockReason) {
  reason = 'blocked: ' + r.promptFeedback.blockReason;
} else {
  const parts = (((r.candidates || [])[0] || {}).content || {}).parts || [];
  raw = parts.map((p) => p.text || '').join('').trim();
  if (!raw) reason = 'empty response';
}

let data = null;
if (raw) {
  const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { data = JSON.parse(cleaned); }
  catch (e) {
    const m = cleaned.match(/\{[\s\S]*\}/);
    if (m) { try { data = JSON.parse(m[0]); } catch (e2) { data = null; } }
  }
}

const s = (v) => (v == null ? '' : typeof v === 'string' ? v : JSON.stringify(v));
let text = '';

if (data && typeof data === 'object') {
  const h = data.hook || {};
  const c = data.cta || {};
  const d = data.creator_delivery || {};
  const L = [];
  if (data.video_available === false) L.push('VIDEO NOT AVAILABLE. Generic blueprint only.');
  L.push('FORMAT: ' + s(data.format) + (data.duration_seconds ? ' | reference length ~' + data.duration_seconds + 's' : '') + (data.spoken_language_style ? ' | ' + s(data.spoken_language_style) : ''));
  L.push('HOOK TECHNIQUE: ' + s(h.technique) + ' | first 3s ~' + s(h.first_3s_word_count) + ' words | delivery: ' + s(h.delivery));
  if (h.why_it_stops_the_scroll) L.push('WHY THE HOOK WORKS: ' + s(h.why_it_stops_the_scroll));
  if (Array.isArray(data.beats) && data.beats.length) {
    L.push('BEAT MAP:');
    for (const b of data.beats) {
      L.push('- ' + s(b.time) + ' | ' + s(b.purpose) + ' | ~' + s(b.approx_words) + ' words | pacing: ' + s(b.pacing) + (b.creator_does ? ' | creator does: ' + s(b.creator_does) : ''));
    }
  }
  if (data.skeleton) L.push('SKELETON: ' + s(data.skeleton));
  L.push('CREATOR DELIVERY: presence: ' + s(d.on_camera_presence) + ' | energy and speed: ' + s(d.energy_and_speed) + ' | editing: ' + s(d.editing_style));
  L.push('CTA: at ' + s(c.timestamp) + ' | type: ' + s(c.type) + ' | framing: ' + s(c.framing) + ' | delivery: ' + s(c.delivery));
  if (Array.isArray(data.retention_devices) && data.retention_devices.length) L.push('RETENTION DEVICES: ' + data.retention_devices.map(s).join('; '));
  if (data.emotional_arc) L.push('EMOTIONAL ARC: ' + s(data.emotional_arc));
  if (data.tone) L.push('TONE: ' + s(data.tone));
  text = L.join('\n');
} else if (raw) {
  text = raw; // model ignored JSON: still usable as plain text
}

const analysisOk = text.length > 120 && !(data && data.video_available === false) && prev.videoStatus === 'ok';
if (!analysisOk) {
  const why = prev.videoStatus !== 'ok' ? prev.videoStatus : (reason || 'too short');
  text =
    'VIDEO ANALYSIS UNAVAILABLE (' + why + '). ' +
    'Do not claim to have seen the reel. Use a generic high-retention short-form skeleton: hook -> problem -> value -> proof -> CTA. Take all content ONLY from the Topic, Purpose and Document.';
}

return [{ json: { analysis: text, analysisOk, analysisReason: reason, videoStatus: prev.videoStatus, videoReason: prev.videoReason || '' } }];

// No Ref Blueprint: used when the user sends NO reference video. Produces the same output shape as "Extract Analysis"
// so Build Master Prompt works unchanged. Priority then is: Topic + Purpose first, Brand info second.
return [{
  json: {
    analysis: 'NO REFERENCE VIDEO PROVIDED. Do not mention any reference. Build the structure yourself using a high-retention short-form skeleton: hook -> problem -> value -> proof -> CTA. All content comes from Topic and Purpose first, then Brand info (tone, audience, USPs, facts).',
    analysisOk: false,
    analysisReason: '',
    videoStatus: 'no_ref',
    videoReason: ''
  }
}];

// Parse Gemini Script (TIER 1): quota / key / model / block errors are caught here; flow moves to Groq key 1 on failure.
const r = $input.first().json;

let text = '';
let error = '';

if (r.error) {
  error = (typeof r.error === 'string'
    ? r.error
    : ((r.error.message || '') + ' ' + (r.error.description || '')).trim() || JSON.stringify(r.error)
  ).toString().slice(0, 300);
} else if (r.promptFeedback && r.promptFeedback.blockReason) {
  error = 'blocked: ' + r.promptFeedback.blockReason;
} else {
  const cand = (r.candidates || [])[0] || {};
  const parts = (cand.content && cand.content.parts) || [];
  text = parts.map((p) => p.text || '').join('').trim();
  if (!text) error = 'empty response' + (cand.finishReason ? ' (' + cand.finishReason + ')' : '');
}

// Accept new script template OR revised FINAL SCRIPT template
const ok =
  text.length > 200 &&
  (/FULL SPOKEN/i.test(text) || /FINAL SCRIPT/i.test(text)) &&
  (/HOOK/i.test(text) || /CTA/i.test(text));
if (!ok && !error) error = 'response did not match the script template';

return [{ json: { ok, text: ok ? text : '', engine: 'gemini', error: ok ? '' : error } }];

// Parse Groq1 result: usable script or move to next tier.
const r = $input.first().json;
const prevErr = $('Parse Gemini Script').first().json.error;

let text = '';
let error = '';

if (r.error) {
  error = (typeof r.error === 'string'
    ? r.error
    : ((r.error.message || '') + ' ' + (r.error.description || '')).trim() || JSON.stringify(r.error)
  ).toString().slice(0, 300);
} else {
  text = String((((r.choices || [])[0] || {}).message || {}).content || '').trim();
  if (!text) error = 'empty response';
}

const ok =
  text.length > 200 &&
  (/FULL SPOKEN/i.test(text) || /FINAL SCRIPT/i.test(text)) &&
  (/HOOK/i.test(text) || /CTA/i.test(text));
if (!ok && !error) error = 'response did not match the script template';

const LABEL = 'Groq1';
const chain = 'Gemini: ' + prevErr + ' | Groq1: ' + error;

return [{ json: { ok, text: ok ? text : '', engine: LABEL.toLowerCase(), error: ok ? '' : chain } }];

// Parse Groq2 result: last fallback tier.
const r = $input.first().json;
const prevErr = $('Parse Groq 1').first().json.error;

let text = '';
let error = '';

if (r.error) {
  error = (typeof r.error === 'string'
    ? r.error
    : ((r.error.message || '') + ' ' + (r.error.description || '')).trim() || JSON.stringify(r.error)
  ).toString().slice(0, 300);
} else {
  text = String((((r.choices || [])[0] || {}).message || {}).content || '').trim();
  if (!text) error = 'empty response';
}

const ok =
  text.length > 200 &&
  (/FULL SPOKEN/i.test(text) || /FINAL SCRIPT/i.test(text)) &&
  (/HOOK/i.test(text) || /CTA/i.test(text));
if (!ok && !error) error = 'response did not match the script template';

const LABEL = 'Groq2';
const chain = prevErr + ' | Groq2: ' + error;

return [{ json: { ok, text: ok ? text : '', engine: LABEL.toLowerCase(), error: ok ? '' : chain } }];

// Parse Input v5: Telegram update -> one of three modes
//   'new'      : Brand / Topic / Purpose (+ optional Ref) -> normal script generation
//   'revise'   : user REPLIES to a bot message with a change request -> script revision
//   'callback' : user tapped an inline button (hook / CTA select, Final Script)
// ALLOWED_CHAT_IDS: ONLY these Telegram IDs can use the bot.
// Empty array = nobody is allowed (fail closed).

const ALLOWED_CHAT_IDS = [8264009249, 7009284089];

const upd = $input.first().json;
const cq = upd.callback_query;
const msg = cq ? cq.message : upd.message;
if (!msg) return [];

const chatId = msg.chat && msg.chat.id;
const fromId = cq ? (cq.from && cq.from.id) : (msg.from && msg.from.id);

const USAGE =
  'Send a message in this format:\n\n' +
  'Brand: <brand name>\n' +
  'Topic: <topic>\n' +
  'Purpose: <goal of the reel>\n' +
  'Ref: <optional - Drive file / folder / direct video link>\n' +
  'Language: Hinglish / Hindi / Gujarati / English\n' +
  'Note: <optional>\n\n' +
  'To revise a script, reply to the bot message and write what to change.';

const escH = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fail = (errorMessage) => [{ json: { valid: false, chatId, errorMessage: escH(errorMessage) } }];

// ---- Authorization ----
const allowed = ALLOWED_CHAT_IDS.map(Number);
if (!allowed.includes(Number(chatId)) && !allowed.includes(Number(fromId))) {
  return fail('You are not a valid user.');
}

// ---- Inline button tap ----
if (cq) {
  const msgText = String(msg.text || msg.caption || '');
  return [{
    json: {
      valid: true,
      mode: 'callback',
      chatId,
      callbackId: cq.id,
      messageId: msg.message_id,
      data: String(cq.data || ''),
      messageText: msgText,
    },
  }];
}

const raw = (msg.text || msg.caption || '').replace(/\r/g, '');

// Key aliases -> canonical field
const KEYS = {
  'brand': 'brand', 'brand name': 'brand', 'brand_name': 'brand', 'client': 'brand', 'company': 'brand',
  'topic': 'topic',
  'purpose': 'purpose', 'goal': 'purpose', 'objective': 'purpose', 'concept': 'purpose',
  'ref': 'ref', 'ref link': 'ref', 'ref video': 'ref', 'reference': 'ref', 'reference link': 'ref', 'reference video': 'ref',
  'video': 'ref', 'video link': 'ref', 'drive': 'ref', 'drive link': 'ref', 'folder': 'ref', 'folder link': 'ref',
  'language': 'language', 'lang': 'language',
  'note': 'note', 'notes': 'note', 'additional note': 'note', 'additional notes': 'note',
};
const alt = Object.keys(KEYS)
  .sort((a, b) => b.length - a.length)
  .map((k) => k.replace(/\s+/g, '\\s+'))
  .join('|');
const keyRe = new RegExp('^\\s*(?:[-*\\u2022>]|\\d+[.)])?\\s*(' + alt + ')\\s*[:=\\-\\u2013]\\s*(.*)$', 'i');

const fields = {};
let current = null;
for (const line of raw.split('\n')) {
  const m = line.match(keyRe);
  if (m) {
    current = KEYS[m[1].toLowerCase().replace(/\s+/g, ' ')];
    fields[current] = (fields[current] ? fields[current] + '\n' : '') + m[2];
  } else if (current) {
    fields[current] += '\n' + line;
  }
}
for (const k of Object.keys(fields)) fields[k] = fields[k].trim();

// ---- Reply to a bot message (and NOT a complete new request) = revision ----
const replied = msg.reply_to_message;
const isFullNew = !!(fields.brand && fields.topic && fields.purpose);
if (replied && !isFullNew) {
  if (!raw.trim()) {
    return fail('To revise, reply with what you want changed.');
  }
  return [{
    json: {
      valid: true,
      mode: 'revise',
      chatId,
      revisionText: raw.trim(),
      repliedMessageId: replied.message_id,
      repliedText: String(replied.text || replied.caption || ''),
    },
  }];
}

if (!fields.brand) return fail('"Brand:" is missing.\n\n' + USAGE);
if (!fields.topic) return fail('"Topic:" is missing.\n\n' + USAGE);
if (!fields.purpose) return fail('"Purpose:" is missing.\n\n' + USAGE);

// ---- Reference video link (OPTIONAL) ----
const urlRe = /https?:\/\/[^\s<>"')\]]+/gi;
const refField = (fields.ref || '').match(urlRe);
const driveAnywhere = (raw.match(urlRe) || []).find((u) =>
  /drive\.google\.com|docs\.google\.com|dropbox\.com/i.test(u)
);
const refUrlRaw = refField ? refField[0] : (driveAnywhere || '');

if (/instagram\.com/i.test(refUrlRaw)) {
  return fail(
    'Instagram links are not supported. Use a Drive file/folder link, a direct video link, or leave Ref empty.\n\n' +
    USAGE
  );
}

let refType = 'none';
let refId = '';
let refUrl = refUrlRaw.replace(/[.,;]+$/, '');

if (refUrl) {
  refType = 'direct';
  const folderM = refUrl.match(
    /drive\.google\.com\/(?:drive\/(?:u\/\d+\/)?folders\/|folderview\?id=)([A-Za-z0-9_-]+)/i
  );
  const fileM =
    refUrl.match(/drive\.google\.com\/file\/(?:u\/\d+\/)?d\/([A-Za-z0-9_-]+)/i) ||
    refUrl.match(/(?:drive|docs)\.google\.com\/(?:uc|open)\?[^#]*?\bid=([A-Za-z0-9_-]+)/i);

  if (folderM) {
    refType = 'folder';
    refId = folderM[1];
  } else if (fileM) {
    refType = 'drivefile';
    refId = fileM[1];
  } else if (/dropbox\.com/i.test(refUrl)) {
    refUrl = refUrl.replace(/([?&])dl=0/i, '$1dl=1');
    if (!/[?&]dl=1/i.test(refUrl)) {
      refUrl += (refUrl.includes('?') ? '&' : '?') + 'dl=1';
    }
  }
}

// ---- Language ----
let language = 'Hinglish';
const l = (fields.language || '').toLowerCase();
if (/hinglish/.test(l)) language = 'Hinglish';
else if (/gujarati|ગુજરાતી/.test(l)) language = 'Gujarati';
else if (/hindi|हिंदी|हिन्दी/.test(l)) language = 'Hindi';
