 // Handle Callback — STATELESS (safe with queue + 2 workers)
 // callback_data format: "selH:selC:action"
 // action = h1|h2|h3|c1|c2|c3|f
 // Final only when one hook AND one CTA are selected.

const p = $('Parse Input').first().json;
const esc = (s) =>
  String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const out = (o) => [{
  json: Object.assign({
    action: 'none',
    callbackId: p.callbackId,
    chatId: p.chatId,
    messageId: p.messageId,
    answerText: '',
    alert: false,
    showFinal: false,
    kb: [],
    finalCb: '',
    lastHtml: '',
    finalText: '',
  }, o),
}];

const snip = (t) => {
  const y = String(t).replace(/\s+/g, ' ').trim();
  return y.length > 34 ? y.slice(0, 34).trim() + '…' : y;
};

const fullText = String(p.messageText || '').replace(/\r/g, '');

function parseScript(text) {
  const hooks = [];
  const ctas = [];
  const body = [];
  let sec = null;

  for (const line of text.split('\n')) {
    const tl = line.trim();

    // Section headers (with or without old emojis)
    if (
      /^(🪝\s*)?HOOK\s*OPTIONS?/i.test(tl) ||
      /^HOOKS?\s*$/i.test(tl)
    ) {
      sec = 'h';
      continue;
    }

    if (
      /^(🎙\s*)?FULL\s*SPOKEN\s*SCRIPT/i.test(tl) ||
      /^SCRIPT\s*$/i.test(tl)
    ) {
      sec = 's';
      continue;
    }

    if (
      /^(📣\s*)?CTA\s*OPTIONS?/i.test(tl) ||
      /^CTAS?\s*$/i.test(tl)
    ) {
      sec = 'c';
      continue;
    }

    if (!tl || /^[━\-—]+$/.test(tl)) continue;

    if (sec === 'h') {
      const m = tl.match(
        /^hook\s*\d+\s*[:：\-–.)]\s*(.+)$/i
      );
      if (m) hooks.push(m[1].trim());
    } else if (sec === 'c') {
      const m = tl.match(
        /^cta\s*\d+\s*[:：\-–.)]\s*(.+)$/i
      );
      if (m) ctas.push(m[1].trim());
    } else if (sec === 's') {
      body.push(tl);
    }
  }

  return { hooks, ctas, body };
}

const parsed = parseScript(fullText);

if (parsed.hooks.length < 3 || parsed.ctas.length < 3) {
  return out({
    answerText:
      'Could not read hooks/CTAs from this message. Please generate a new script.',
    alert: true,
  });
}

// Parse "selH:selC:action"
const parts = String(p.data || '').split(':');
let selH = Number(parts[0]) || 0;
let selC = Number(parts[1]) || 0;
const action = String(parts[2] || '').toLowerCase();

if (action.startsWith('h')) {
  const n = Number(action.slice(1));

  if (!(n >= 1 && n <= 3)) {
    return out({ answerText: 'Invalid hook.', alert: true });
  }

  selH = selH === n ? 0 : n; // toggle

} else if (action.startsWith('c')) {
  const n = Number(action.slice(1));

  if (!(n >= 1 && n <= 3)) {
    return out({ answerText: 'Invalid CTA.', alert: true });
  }

  selC = selC === n ? 0 : n;

} else if (action === 'f') {
  if (!(selH >= 1 && selH <= 3 && selC >= 1 && selC <= 3)) {
    return out({
      answerText: 'Select one hook and one CTA first.',
      alert: true,
    });
  }

  const hook = parsed.hooks[selH - 1] || '';
  const cta = parsed.ctas[selC - 1] || '';
  const spokenLines = [...parsed.body];

  if (!spokenLines.length) {
    return out({
      answerText:
        'Spoken script not found. Please generate it again.',
      alert: true,
    });
  }

  const norm = (s) =>
    String(s)
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase();

  function splitTimestamp(line) {
    const m = String(line).match(
      /^(\s*\[\d+\s*-\s*\d+s\]\s*)(.*)$/i
    );

    return m
      ? { prefix: m[1], content: m[2] }
      : { prefix: '', content: String(line) };
  }

  // HOOK: put the selected hook at the beginning.
  // Remove an existing generated hook if it matches a hook option.
  const first = splitTimestamp(spokenLines[0]);
  let opening = first.content.trim();

  const existingHook = parsed.hooks.find((h) =>
    norm(opening).startsWith(norm(h))
  );

  if (existingHook) {
    opening = opening
      .slice(existingHook.length)
      .replace(/^[\s,;:—-]+/, '')
      .trim();
  } else {
    // If the opening is a different hook, remove its first sentence.
    const sentence = opening.match(/^.*?[.!?](?:\s+|$)/);
    if (sentence) {
      opening = opening.slice(sentence[0].length).trim();
    }
  }

  spokenLines[0] =
    first.prefix +
    hook +
    (opening ? ' ' + opening : '');

  // CTA: put the selected CTA at the end.
  // Replace the final spoken line so the CTA isn't duplicated.
  const lastIndex = spokenLines.length - 1;
  const last = splitTimestamp(spokenLines[lastIndex]);

  spokenLines[lastIndex] = last.prefix + cta;

  // Escape HTML and retain timestamp formatting.
  const bodyLines = spokenLines.map((line) =>
    esc(line).replace(
      /^(\s*\[\d+\s*-\s*\d+s\])/,
      '<b>$1</b>'
    )
  );

  const text =
    '<b>FINAL SCRIPT</b>\n\n' +
    '<b>FULL SPOKEN SCRIPT — RECORD THIS VERSION</b>\n' +
    bodyLines.join('\n');

  return out({
    action: 'final',
    finalText: text.slice(0, 4000),
  });

} else {
  return out({ answerText: 'Unknown action.', alert: true });
}

function kbData(h, c) {
  const rows = [];

  parsed.hooks.forEach((text, i) => {
    const n = i + 1;

    rows.push({
      text: (h === n ? '[x] ' : '[ ] ') +
        'Hook ' + n + ': ' + snip(text),
      cb: h + ':' + c + ':h' + n,
    });
  });

  parsed.ctas.forEach((text, i) => {
    const n = i + 1;

    rows.push({
      text: (c === n ? '[x] ' : '[ ] ') +
        'CTA ' + n + ': ' + snip(text),
      cb: h + ':' + c + ':c' + n,
    });
  });

  return rows;
}

const showFinal = selH >= 1 && selC >= 1;

let label = 'Updated';

if (action.startsWith('h')) {
  label = selH
    ? ('Hook ' + selH + ' selected')
    : 'Hook cleared';
}

if (action.startsWith('c')) {
  label = selC
    ? ('CTA ' + selC + ' selected')
    : 'CTA cleared';
}

// Keep the original message body; only keyboard changes.
const lastHtml = esc(fullText).slice(0, 4000);

return out({
  action: 'edit',
  answerText: label,
  showFinal,
  kb: kbData(selH, selC),
  finalCb: selH + ':' + selC + ':f',
  lastHtml,
});

// Load Revision Context — STATELESS (v2 - Conservative Revision)
// Revises the message the user replied to (usually FINAL SCRIPT).
// Strongly preserves concept, structure and key points.

const p = $('Parse Input').first().json;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const prev = String(p.repliedText || '').trim();
const req = String(p.revisionText || '').trim();

if (!prev || prev.length < 40) {
  return [{
    json: {
      ok: false,
      errorMessage: esc(
        'Could not find a script in the message you replied to. Reply to the Final Script message and write what to change.'
      ),
    },
  }];
}
if (!req) {
  return [{
    json: {
      ok: false,
      errorMessage: esc('Reply with what you want changed.'),
    },
  }];
}

const SYSTEM = `You are a precise Instagram Reel script editor.

Your job is to make ONLY the changes the user requested — nothing more.

CORE PRINCIPLE:
Preserve the original script's concept, structure, key points, examples, tone and overall meaning as much as possible.

STRICT RULES:

