  'Return the complete revised script only, using the exact format above.';

const GEMINI_MODEL = 'gemini-3.1-flash-lite';
const GROQ_MODEL = 'openai/gpt-oss-120b';

const geminiBody = {
  systemInstruction: { parts: [{ text: SYSTEM }] },
