    { role: 'system', content: SYSTEM },
    { role: 'user', content: USER },
  ],
};

return [{
  json: {
    ok: true,
    mode: 'revise',
    geminiModel: GEMINI_MODEL,
    groqModel: GROQ_MODEL,
    geminiBody,
    groqBody,
