return [{ json: $input.first().json }];

// Format for Telegram v5 — STATELESS (queue + 2 workers safe)
// Sends hooks + full spoken script + CTAs only.
// Inline select buttons use callback_data "selH:selC:action" (no session store).

const LIMIT = 3800;
const chatId = $('Parse Input').first().json.chatId;
const inp = $input.first().json;
const master = $('Prompt Source').first().json;

const esc = (s) =>
  String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// kind 'script' = message with select buttons; kind 'plain' = everything else
const mk = (text, extra) => ({
  json: Object.assign({ chatId, text, kind: 'plain' }, extra || {}),
});

// -------------------- ERROR --------------------
if (!inp.ok) {
  const errStr = String(inp.error || 'unknown error');
  const hints = [];
  if (/Gemini:[^|]*(401|403|UNAUTH|PERMISSION|API key)/i.test(errStr)) {
    hints.push(
      'Gemini auth: Header Auth credential Name = x-goog-api-key, Value = AI Studio API key (no Bearer).'
    );
  }
  if (/Groq[12]:[^|]*(401|invalid_api_key)/i.test(errStr)) {
    hints.push(
      'Groq auth: Header Auth Name = Authorization, Value = Bearer gsk_xxx'
    );
  }
  if (/Groq[12]:[^|]*(404|model_not_found)/i.test(errStr)) {
    hints.push(
      'Groq model: enable model access in console.groq.com, or change GROQ_MODEL in Build Master Prompt.'
    );
  }
  if (/(429|rate|quota|exhausted|too many)/i.test(errStr)) {
    hints.push('Rate limit / quota: wait 1-2 minutes and try again.');
  }
  return [
    mk(
      '<b>Script generation failed</b>\n' +
        'Gemini, Groq key 1 and Groq key 2 all failed.\n\n' +
        esc(errStr.slice(0, 700)) +
        (hints.length ? '\n\n' + esc(hints.join('\n')) : '')
    ),
  ];
}

// -------------------- CLEAN MODEL TEXT --------------------
let t = String(inp.text || '')
  .replace(/\r/g, '')
  .replace(/```[a-z]*\n?/gi, '')
  .replace(/\*\*(.+?)\*\*/g, '$1')
  .replace(/__(.+?)__/g, '$1')
  .replace(/^#{1,6}\s+/gm, '')
  .replace(/^\s*[-*]\s+/gm, '• ')
  .trim();

let all = t.split('\n');

// Drop intro before hooks / final script
const start = all.findIndex(
  (l) =>
    /^\s*(🪝|HOOK\s*OPTIONS?|FINAL\s*SCRIPT)/i.test(l)
);
if (start > 0) all = all.slice(start);

// Drop caption / hashtags / anything after CTA block
const stop = all.findIndex((l) =>
  /^\s*(📝|🔖|🏷|🎬|CAPTION|HASHTAG)/i.test(l)
);
if (stop >= 0) all = all.slice(0, stop);

// Drop trailing separators / blank lines
while (
  all.length &&
  (!all[all.length - 1].trim() || /^[━\-—]+$/.test(all[all.length - 1].trim()))
) {
  all.pop();
}

// -------------------- PARSE SECTIONS --------------------
const hooks = [];
const ctas = [];
const body = [];
let sec = null;
let isFinalOnly = false;

for (const line of all) {
  const tl = line.trim();

  if (/^(🪝\s*)?HOOK\s*OPTIONS?/i.test(tl) || /^HOOKS?\s*$/i.test(tl)) {
    sec = 'h';
    continue;
  }
  if (/^(🎙\s*)?FULL\s*SPOKEN\s*SCRIPT/i.test(tl) || /^SCRIPT\s*$/i.test(tl)) {
    sec = 's';
    continue;
  }
  if (/^(📣\s*)?CTA\s*OPTIONS?/i.test(tl) || /^CTAS?\s*$/i.test(tl)) {
    sec = 'c';
    continue;
  }
  if (/^FINAL\s*SCRIPT/i.test(tl)) {
    isFinalOnly = true;
    sec = 'final';
    continue;
  }
  if (/^(HOOK)\s*$/i.test(tl) && isFinalOnly) {
    sec = 'fh';
    continue;
  }
  if (/^(FULL\s*SPOKEN\s*SCRIPT)\s*$/i.test(tl) && isFinalOnly) {
    sec = 'fs';
    continue;
  }
  if (/^(CTA)\s*$/i.test(tl) && isFinalOnly) {
    sec = 'fc';
    continue;
  }

  if (!tl || /^[━\-—]+$/.test(tl)) continue;

  if (sec === 'h') {
    const m = tl.match(/^hook\s*\d+\s*[:：\-–.)]\s*(.+)$/i);
    if (m) hooks.push(m[1].trim());
  } else if (sec === 'c') {
    const m = tl.match(/^cta\s*\d+\s*[:：\-–.)]\s*(.+)$/i);
    if (m) ctas.push(m[1].trim());
  } else if (sec === 's' || sec === 'fs' || sec === 'fh' || sec === 'fc' || sec === 'final') {
    body.push(tl);
  }
}

// -------------------- STATELESS BUTTONS (no session store) --------------------
function kbData() {
  const snip = (x) => {
    const y = String(x).replace(/\s+/g, ' ').trim();
    return y.length > 34 ? y.slice(0, 34).trim() + '…' : y;
  };
  const rows = [];
  hooks.forEach((h, i) =>
    rows.push({
      text: '[ ] Hook ' + (i + 1) + ': ' + snip(h),
      cb: '0:0:h' + (i + 1),
    })
  );
  ctas.forEach((c, i) =>
    rows.push({
      text: '[ ] CTA ' + (i + 1) + ': ' + snip(c),
      cb: '0:0:c' + (i + 1),
    })
  );
  return rows;
}

const canKb = !isFinalOnly && hooks.length === 3 && ctas.length === 3;

// -------------------- HTML MESSAGE --------------------
const lines = all.map((line) => {
  let trimmed = line.trim()
    .replace(/^🪝\s*/g, 'HOOK OPTIONS')
    .replace(/^🎙\s*/g, 'FULL SPOKEN SCRIPT')
    .replace(/^📣\s*/g, 'CTA OPTIONS')
    .replace(/^🎬\s*/g, '');

  let l = esc(trimmed);

  if (
    /^(HOOK OPTIONS|FULL SPOKEN SCRIPT|CTA OPTIONS|FINAL SCRIPT|HOOK|CTA)\s*$/i.test(
      trimmed
    )
  ) {
    return '<b>' + l + '</b>';
  }
  l = l.replace(/^(\s*\[\d+\s*-\s*\d+s\])/, '<b>$1</b>');
  l = l.replace(/^(\s*Hook\s*\d+:)/i, '<b>$1</b>');
  l = l.replace(/^(\s*CTA\s*\d+:)/i, '<b>$1</b>');
  return l;
});

// Reference video warnings (only when a ref was sent but could not be used)
const warn = [];
if (
  master.videoStatus &&
  master.videoStatus !== 'ok' &&
  master.videoStatus !== 'no_ref'
) {
  const why =
    {
      too_large: 'video is larger than 14 MB (compress and retry)',
      download_failed: 'video could not be downloaded from Drive',
    }[master.videoStatus] || master.videoStatus;
  warn.push(
    'Reference video was not analysed: ' +
      why +
      (master.videoReason ? ' [' + master.videoReason + ']' : '') +
      '. Script below uses a generic structure.'
  );
} else if (master.videoStatus !== 'no_ref' && master.analysisOk === false) {
  warn.push(
    'Reference video analysis failed. Script below uses a generic structure.'
  );
}

const joined = lines.join('\n');

// New script with 3 hooks + 3 CTAs → buttons
if (canKb && joined.length <= 4000) {
  const it = mk(joined, { kind: 'script', kb: kbData() });
  const res = [it];
  if (warn.length) res.unshift(mk(esc(warn.join('\n'))));
  return res;
}

// Final-only (revise result) or long script → plain text, no buttons
const chunks = [];
let cur = '';
const push = () => {
  if (cur.trim()) chunks.push(cur);
  cur = '';
};

for (const line of lines) {
  const isSep = /^[━\-—]+$/.test(line.trim());
  const next = cur ? cur.length + 1 + line.length : line.length;
  if (cur && (next > LIMIT || (isSep && cur.length > 2800))) push();
  if (line.length > LIMIT) {
    const plain = line.replace(/<\/?b>|<\/?i>/g, '');
    for (let i = 0; i < plain.length; i += LIMIT) {
      cur = plain.slice(i, i + LIMIT);
      push();
    }
    continue;
  }
  cur += (cur ? '\n' : '') + line;
}
push();

const outItems = chunks.map((c, i) =>
  mk(
    chunks.length > 1
      ? c + '\n\n<i>(' + (i + 1) + '/' + chunks.length + ')</i>'
      : c
  )
);
if (warn.length) outItems.unshift(mk(esc(warn.join('\n'))));
return outItems;

// No session map (stateless). Only forwards failed Telegram sends to Send Fallback as plain text.

const src = $('Format for Telegram').all().filter((x) => x.json.kind === 'script');
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const failed = [];
let firstErr = '';

$input.all().forEach((it, i) => {
  const j = it.json || {};
  const r = j.result || j;
  const mid = r && r.message_id;
  const meta = (src[i] && src[i].json) || {};
  if (!mid) {
    if (!firstErr) {
      const e = j.error;
      firstErr =
        (e && (e.description || e.message)) ||
        j.description ||
        (typeof e === 'string' ? e : '') ||
        'no response from Telegram Bot API';
    }
    failed.push({ chatId: meta.chatId, text: meta.text || '' });
  }
});

if (!failed.length) return [];

const out = [{
  json: {
    chatId: failed[0].chatId,
    text:
      'Could not send the message with buttons. Script is below as plain text.\n' +
      esc(String(firstErr).slice(0, 300)),
  },
}];
failed.forEach((f) => {
  if (f.text) out.push({ json: { chatId: f.chatId, text: f.text } });
});
return out;
